              "Global Accelerator는 애니캐스트 IP로 사용자를 가장 가까운 AWS 엣지로 라우팅하고, 정상/비정상 엔드포인트 간 자동 장애 조치를 지원하여 캐시 불가능한 게이밍/IoT/VoIP 트래픽에 적합하다",
